/bin/zsh -lc "python3 -c 'import json
wanted={\"저장하다\",\"확인하다\",\"요청하다\",\"승인하다\",\"첨부하다\",\"전송하다\",\"대기하다\",\"스캔하다\",\"해제하다\",\"권고하다\",\"유지하다\"}
def visit(x):
    if isinstance(x,dict):
        if x.get(\"lemma\") in wanted:
            print(json.dumps({k:v for k,v in x.items() if k in {\"lemma\",\"meaning\",\"pos\",\"allowed_forms\",\"patterns\",\"conditions\",\"status\",\"deprecated\",\"argument_patterns\",\"usage_conditions\"}},ensure_ascii=False))
        else:
            for v in x.values(): visit(v)
    elif isinstance(x,list):
        for v in x: visit(v)
for p in [\"lexicon/core.json\",\"lexicon/domains/software.json\"]:
    with open(p) as f: visit(json.load(f))'"

